package vn.rtr.aeris.cockpit03;
import java.io.*;
import java.util.*;
import org.json.*;
import vn.rtr.aeris.beta01runtime.Values;
public final class WorkspaceDomain {
 private static double number(JSONObject o,String k,double min,double max)throws Exception{Object v=o.get(k);if(!(v instanceof Number))throw new IOException("DRAFT_NUMBER_TYPE:"+k);double d=((Number)v).doubleValue();if(!Double.isFinite(d)||d<min||d>max)throw new IOException("DRAFT_NUMBER_RANGE:"+k);return d;}
 public static byte[]draft(JSONObject o,String existingId,int expected)throws Exception{Set<String>allowed=new HashSet<>(Arrays.asList("revision","kind","name","datum","altitudeDatum","units","geometry","altitudeM","corridorWidthM"));Iterator<String>keys=o.keys();while(keys.hasNext())if(!allowed.contains(keys.next()))throw new IOException("DRAFT_UNKNOWN_FIELD");if(!(o.get("revision") instanceof Number)||o.getDouble("revision")!=expected)throw new IOException("DRAFT_REVISION");String kind=o.getString("kind"),name=o.getString("name");if(!Arrays.asList("polygon","corridor").contains(kind)||name.trim().isEmpty()||name.length()>80||name.chars().anyMatch(c->c<32))throw new IOException("DRAFT_KIND_OR_NAME");if(!"WGS84".equals(o.getString("datum"))||!"RELATIVE_HOME".equals(o.getString("altitudeDatum"))||!"m".equals(o.getString("units")))throw new IOException("DRAFT_DATUM_UNITS");JSONArray a=o.getJSONArray("geometry");if(a.length()<(kind.equals("polygon")?3:2)||a.length()>64)throw new IOException("DRAFT_GEOMETRY_COUNT");ArrayList<Object>geometry=new ArrayList<>();Set<String>unique=new HashSet<>();for(int i=0;i<a.length();i++){JSONArray p=a.getJSONArray(i);if(p.length()!=2||!(p.get(0)instanceof Number)||!(p.get(1)instanceof Number))throw new IOException("DRAFT_COORD_TYPE");double lat=p.getDouble(0),lon=p.getDouble(1);if(!Double.isFinite(lat)||!Double.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180)throw new IOException("DRAFT_WGS84");geometry.add(Arrays.asList(lat,lon));unique.add(lat+":"+lon);}if(unique.size()!=a.length())throw new IOException("DRAFT_DUPLICATE_VERTEX");validateGeometry(geometry,kind);return Values.bytes(Values.map("version",1,"id",existingId==null?"survey-"+UUID.randomUUID():existingId,"revision",expected+1,"kind",kind,"name",name.trim(),"datum","WGS84","altitudeDatum","RELATIVE_HOME","units","m","geometry",geometry,"altitudeM",number(o,"altitudeM",1,5),"corridorWidthM",number(o,"corridorWidthM",1,100),"trainingOnly",true));}
 private static void validateGeometry(ArrayList<Object> points,String kind)throws IOException{int n=points.size();double[][]xy=new double[n][2];List<?>origin=(List<?>)points.get(0);double lat0=((Number)origin.get(0)).doubleValue(),lon0=((Number)origin.get(1)).doubleValue();for(int i=0;i<n;i++){List<?>p=(List<?>)points.get(i);double lat=((Number)p.get(0)).doubleValue(),lon=((Number)p.get(1)).doubleValue();if(Math.abs(lon-lon0)>180)throw new IOException("DRAFT_ANTIMERIDIAN_UNSUPPORTED");xy[i][0]=(lon-lon0)*111319.49079327357*Math.cos(Math.toRadians(lat0));xy[i][1]=(lat-lat0)*111319.49079327357;if(Math.hypot(xy[i][0],xy[i][1])>1000)throw new IOException("DRAFT_LOCAL_REFERENCE_MAX_1KM");if(i>0&&Math.hypot(xy[i][0]-xy[i-1][0],xy[i][1]-xy[i-1][1])<.1)throw new IOException("DRAFT_SEGMENT_DEGENERATE");}if(kind.equals("polygon")){double area=0;for(int i=0;i<n;i++)area+=xy[i][0]*xy[(i+1)%n][1]-xy[(i+1)%n][0]*xy[i][1];if(Math.abs(area)*.5<.1)throw new IOException("DRAFT_POLYGON_AREA_DEGENERATE");for(int i=0;i<n;i++)for(int j=i+1;j<n;j++){if(j==i+1||i==0&&j==n-1)continue;if(intersects(xy[i],xy[(i+1)%n],xy[j],xy[(j+1)%n]))throw new IOException("DRAFT_POLYGON_SELF_INTERSECTION");}}}
 private static double orient(double[]a,double[]b,double[]c){return(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);}
 private static boolean intersects(double[]a,double[]b,double[]c,double[]d){double x=orient(a,b,c),y=orient(a,b,d),z=orient(c,d,a),w=orient(c,d,b);return x*y<=0&&z*w<=0&&Math.max(Math.min(a[0],b[0]),Math.min(c[0],d[0]))<=Math.min(Math.max(a[0],b[0]),Math.max(c[0],d[0]))&&Math.max(Math.min(a[1],b[1]),Math.min(c[1],d[1]))<=Math.min(Math.max(a[1],b[1]),Math.max(c[1],d[1]));}
}
